// Prendre le premier document disponible
const items = $input.all();

if (items.length === 0) {
  // Aucun document trouvé
  return {
    json: {
      noDocument: true,
      message: "Aucun document disponible dans le dossier scans"
    }
  };
}

// Retourner le premier document
return items[0];

// Parser la réponse JSON de l'IA
const aiResponse = $input.item.json.message.content.text || $input.item.json.message.content[0].text || $input.item.json.message.content;
let extractedData;
let errors = [];

try {
  // Nettoyer la réponse (retirer markdown si présent)
  let cleanResponse = aiResponse.trim();
  if (typeof cleanResponse !== 'string') {
    cleanResponse = JSON.stringify(cleanResponse);
  }

  // Retirer markdown code blocks
  if (cleanResponse.includes('```json')) {
    cleanResponse = cleanResponse.replace(/```json[\s\S]*?```/g, (match) => {
      return match.replace(/```json/g, '').replace(/```/g, '').trim();
    });
  } else if (cleanResponse.includes('```')) {
    cleanResponse = cleanResponse.replace(/```[\s\S]*?```/g, (match) => {
      return match.replace(/```/g, '').trim();
    });
  }

  // Extraire JSON si c'est dans une chaîne
  const jsonMatch = cleanResponse.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    cleanResponse = jsonMatch[0];
  }

  extractedData = JSON.parse(cleanResponse);
} catch (error) {
  errors.push(`Erreur parsing JSON: ${error.message}`);
  console.error('Erreur parsing:', error);
  console.error('Réponse reçue:', aiResponse);
  extractedData = {};
}

// Liste des champs à extraire
const fields = [
  'prenom', 'nom', 'date_naissance', 'fonction', 
  'date_embauche', 'societe', 'salaire_brut', 
  'impots', 'cotisations_sociales', 'salaire_net'
];

// Construire la structure de données finale avec value/confidence/justification
const formattedData = {};
const fileName = $input.first().json.fileName || 'unknown';
const fileId = $input.first().json.fileId || null;

fields.forEach(field => {
  if (extractedData[field] && typeof extractedData[field] === 'object') {
    const fieldData = extractedData[field];

    // Vérifier si valeur illisible ou confidence trop faible
    if (fieldData.value === 'illisible' || fieldData.value === 'Illisible' || 
        fieldData.value === null || fieldData.value === undefined ||
        (fieldData.confidence !== undefined && fieldData.confidence < 0.3)) {

      // Déterminer le message d'erreur
      if (fieldData.value === 'illisible' || fieldData.value === 'Illisible') {
        errors.push(`${field}: illisible`);
      } else if (fieldData.confidence < 0.3) {
        errors.push(`${field}: confidence trop faible (${fieldData.confidence || 0})`);
      } else {
        errors.push(`${field}: valeur manquante`);
      }
    }

    // Garder la structure complète (value, confidence, justification)
    formattedData[field] = {
      value: fieldData.value || null,
      confidence: fieldData.confidence !== undefined ? fieldData.confidence : 0.0,
      justification: fieldData.justification || 'Non fourni'
    };
  } else {
    // Champ non extrait
    formattedData[field] = {
      value: null,
      confidence: 0.0,
      justification: 'Champ non extrait par l\'IA'
    };
    errors.push(`${field}: champ non extrait`);
  }
});

// Déterminer le statut
const fieldsWithErrors = errors.length;
const totalFields = fields.length;
let determineStatus;

if (fieldsWithErrors === 0) {
  determineStatus = 'extracted';
} else if (fieldsWithErrors < totalFields / 2) {
  determineStatus = 'partial';
} else {
  determineStatus = 'failed';
}

return {
  filename: fileName,
  fileId: fileId,
  status: determineStatus,
  data: formattedData,
  errors: errors
};

// Construire la réponse finale pour un document unique
const documentData = $input.item.json;

// La structure data contient déjà value/confidence/justification pour chaque champ
// C'est exactement ce qui est demandé dans les spécifications
return {
  status: "success",
  total_documents: 1,
  documents: [
    {
      filename: documentData.filename,
      status: documentData.status,
      data: documentData.data, // Structure complète avec value/confidence/justification pour chaque champ
      errors: documentData.errors || []
    }
  ]
};

// Réponse quand aucun document n'est trouvé
return {
  status: "success",
  total_documents: 0,
  documents: [],
  message: "Aucun document disponible dans le dossier scans"
};
